"OLAYLAR_EK16:1941-07-09:0":{"b": ["Pskov جرمن فوج کے ہاتھوں لیا گیا — روسی علاقوں پر قبضے کا آغاز", "d9822e30"], "d": ["باربروسا کے تیسرے ہفتے میں Wehrmacht Pskov میں داخل ہوئی؛ شہر 23 جولائی 1944 تک جرمن فوجی انتظام میں رہا۔ ماخذ: Pskov شہر کا تاریخی ترتیب نامہ، memorialmuseums.org «Memorials in Pskov» — تلاش کا خلاصہ [خلاصہ]۔", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["جرمن فوج نے Vitebsk پر قبضہ کر لیا", "e1e4d7d0"], "d": ["آرمی گروپ سینٹر نے Barbarossa کے ابتدائی ہفتوں میں Vitebsk لے لیا؛ شہر جون 1944 تک جرمن فوجی انتظامیہ میں رہا اور اس کی آبادی کا بڑا حصہ ختم ہو گیا۔", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Smolensk جرمن فوج کے ہاتھوں لیا گیا", "5a7f4e2a"], "d": ["آرمی گروپ سینٹر نے Smolensk لے لیا؛ ماسکو کے راستے پر واقع یہ شہر 25 ستمبر 1943 تک 26 ماہ قبضے میں رہا اور اسے بڑی تباہی کا سامنا کرنا پڑا۔", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["جرمن فوج نے Mogilev پر قبضہ کر لیا", "4362b7a1"], "d": ["Mogilev 23 دن جاری رہنے والے دفاع کے بعد ویرماخت کے ہاتھ آیا؛ شہر 28 جون 1944 تک قبضے میں رہا۔", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Reichskommissariat Ostland قائم ہوا — بالٹک ممالک اور بیلاروس جرمن سول انتظام میں آ گئے", "052d4c08"], "d": ["ہٹلر کے 17 جولائی 1941 کے فیصلے سے مشرق کے مقبوضہ علاقے سول انتظام کے سپرد کیے گئے؛ Hinrich Lohse کی سربراہی میں Ostland نے ایسٹونیا، لٹویا، لتھوانیا اور بیلاروس کو شامل کیا (مرکز ریگا)۔ ایسٹونیا کا سول انتظام 5 دسمبر 1941 کو، اور بیلاروس کا مشرق فوجی انتظام میں رہا۔", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["جرمن-ایسٹونی دستوں نے Narva پر قبضہ کر لیا", "60fc2b6a"], "d": ["گرمیوں کی جنگ میں ایسٹونی رضاکاروں اور ویرماخت نے Narva لے لیا؛ شہر کو Ostland میں شامل کیا گیا اور 26 جولائی 1944 تک جرمن انتظامیہ میں رہا۔", "0f32445c"]},
