"OLAYLAR_EK2:1462-06-01:0":{"b": ["والاچیا کی مہم: سولی والا ووِووڈ", "fd4530bb"], "d": ["خراج دینے سے انکار کر کے سفیروں کو قتل کرنے والے ولاد تیپیش پر منظم مہم سے والاچیا کو باجگزاری میں لوٹایا گیا؛ رات کا حملہ اور سولی کی ہولناک منظر کشی یورپ میں افسانہ بن گئی۔ اسی تاریخ کو شامل ہونے والے دیگر مقامات: Bükreş۔", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["فاتح کمپلیکس کا افتتاح", "a150ea55"], "d": ["آٹھ مدرسوں (صحنِ ثمان) کے ساتھ کمپلیکس استنبول کو عالمِ اسلام کا علمی مرکز بنانے کے پروگرام کا پہلا بڑا قدم تھا۔", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["علی قوشچی استنبول میں", "8508229d"], "d": ["سمرقند کی رصد گاہ کے آخری بڑے نمائندے علی قوشچی فاتح کی دعوت پر ایاصوفیہ مدرسہ کے مدرس بنے؛ استنبول میں ریاضی-فلکیات کی روایت قائم کی۔", "fd325f60"]},
