"OLAYLAR_EK2:1538-06-13:0":{"b": ["بحرِ ہند کی مہم: دیو کا محاصرہ", "fcd1217a"], "d": ["سویز سے روانہ ہونے والے بیڑے نے بحیرۂ احمر عبور کر کے گجرات کے دیو کا محاصرہ کیا؛ قلعہ نہ لیا جا سکا مگر عثمانی قوت پہلی بار بحرِ ہند تک پہنچی، پرتگالی اجارہ داری ہل گئی۔", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["سیدی علی ریئس کا ہندوستانی سفر", "e5da3b2c"], "d": ["بصرہ کے بیڑے کو مصر لانے پر مامور سیدی علی ریئس طوفانوں کے ساتھ ہندوستان بہہ گئے؛ واپسی کی مہم بیان کرنے والی مرآۃ الممالک پہلے عثمانی سفرناموں میں سے ہے۔", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["پیری ریئس کی پھانسی", "63026444"], "d": ["ہرمز کی مہم سے بیڑا بصرہ میں چھوڑ کر لوٹنے والے عظیم ملاح-نقشہ ساز کو 84 سال کی عمر میں پھانسی دی گئی — ہماری سائنسی تاریخ کے سب سے متنازع فیصلوں میں سے۔", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["سلیمانیہ کمپلیکس کا افتتاح", "1c6458b2"], "d": ["وہ کمپلیکس جسے معمار سنان نے 'اپنی کاریگری کے دور کا کام' کہا؛ اپنے مدرسوں، شفا خانے اور کتب خانے کے ساتھ یہ کلاسیکی دور کا سب سے بڑا تعلیمی و فلاحی مجموعہ بنا۔", "0c203c6b"]},
