"OLAYLAR_EK2:1578-08-09:0":{"b": ["چلدر کی فتح — مشرقی جنگ شروع ہوئی", "13125a54"], "d": ["صفوی فوج کے چلدر میں شکست کھانے سے قفقاز کے دروازے کھلے؛ تفلیس لیا گیا اور جارجیا عثمانی غلبے میں آ گیا۔", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["مشعلوں کی جنگ — شیروان قطعی طور پر عثمانیوں کے پاس", "3bbc23bc"], "d": ["رات کو مشعلوں کی روشنی میں بھی جاری رہنے کی وجہ سے اس نام سے یاد کی جانے والی جنگ میں صفوی قطعی شکست سے دوچار ہوئے؛ شیروان اور باکو میں عثمانی غلبہ پختہ ہوا۔", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["عظیم تغشیش — آقچہ کا بحران", "9205c3d4"], "d": ["طویل جنگوں اور امریکی چاندی کے دباؤ سے آقچہ کا چاندی کا مواد آدھا کر دیا گیا؛ قیمتوں کے انقلاب نے سپاہی نظام کے بکھرنے اور جلالی انتشار کو ہوا دی۔", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["تبریز کی فتح", "6506bdb9"], "d": ["سردار اوزدمیر اوغلو عثمان پاشا تبریز میں داخل ہوئے؛ صفویوں کا قدیم دارالحکومت عثمانی انتظام میں لیا گیا۔ عثمان پاشا چند ہفتے بعد خیمہ گاہ میں وفات پا گئے۔", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["معاہدۂ فرہاد پاشا — مشرق میں وسیع ترین سرحدیں", "c429972f"], "d": ["شاہ عباس کے سفیر حیدر مرزا کے استنبول آنے (18 جنوری 1590) کے بعد، فتح کیے گئے مقامات کے عثمانیوں کے پاس رہنے کی شرط پر کیے گئے اور 12 سالہ جنگ ختم کرنے والے معاہدے سے تبریز، قرہ باغ، شیروان، جارجیا اور لورستان عثمانیوں کے پاس رہے؛ سلطنت مشرق میں اپنی تاریخ کی وسیع ترین سرحدوں تک پہنچی۔", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["عثمانی-صفوی جنگ (1603-1612) شروع ہوئی — شاہ عباس کا جوابی حملہ، تبریز کا نقصان", "abf27dd8"], "d": ["اپنی فوج کو از سرِ نو منظم کرنے والے شاہ عباس نے جلالی انتشار سے فائدہ اٹھا کر حملہ کیا؛ تبریز گرا، قفقاز کے حصول چند سال میں ہاتھ سے گئے۔ اسی مہم اور اس کے بعد ہاتھ سے نکلنے والی دیگر بستیاں: Nahçıvan، Hoy، Merend، Selmâs؛ Karacadağ (Ahar) اور Mukrî بیگ بھی صفوی طرف لوٹ گئے۔", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["اولیا چلبی پیدا ہوئے", "2b6051ff"], "d": ["پچاس سال سے زیادہ کے سفروں کو دس جلدوں کے سیاحت نامے میں جمع کرنے والے اولیا چلبی نے سترھویں صدی کی عثمانی دنیا کا بے مثال منظر چھوڑا۔", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["معاہدۂ نصوح پاشا", "bb69e388"], "d": ["1603 سے جاری جنگ ختم کرنے والے معاہدے سے 1590 کے حصولات چھوڑ دیے گئے اور 1555 کی آماسیہ سرحد پر لوٹا گیا؛ مشرقی محاذ پر توازن دوبارہ قائم ہوا۔", "f3ce47a7"]},
